"use client";

import { AnimatePresence } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Switch } from "@/components/motion/switch";
import { Kbd } from "@/components/ui/kbd";

import { BlockFrame } from "../parts/block-frame";
import { FOLDERS, type Folder, MESSAGES, type Message } from "./inbox-triage/data";
import { FolderTabs } from "./inbox-triage/folder-tabs";
import { MessageRow } from "./inbox-triage/message-row";
import { type Notice, StatusLine } from "./inbox-triage/status-line";

const MOVED = { archive: "Archived", snoozed: "Snoozed until Monday", inbox: "Moved to inbox" } satisfies Record<Folder, string>;

/**
 * A front desk inbox for triage. People switch folders, open a message in
 * place, and archive, snooze or restore it from the keyboard or with the
 * buttons, with an undo for each move.
 */
export function InboxTriage({ className }: { className?: string }) {
  const [messages, setMessages] = useState<Message[]>(MESSAGES);
  const [folder, setFolder] = useState<Folder>("inbox");
  const [unreadOnly, setUnreadOnly] = useState(false);
  const [open, setOpen] = useState<string | null>(null);
  const [notice, setNotice] = useState<Notice | null>(null);
  const list = useRef<HTMLUListElement>(null);
  const focusRow = useRef<number | null>(null);
  const titleId = useId();
  const panelId = useId();
  const switchId = useId();

  const unread = messages.filter((message) => message.folder === "inbox" && message.unread).length;
  const counts = { inbox: 0, snoozed: 0, archive: 0 } satisfies Record<Folder, number>;
  for (const message of messages) counts[message.folder] += 1;
  const rows = messages.filter((message) => message.folder === folder && (!unreadOnly || message.unread));

  // After a move or a folder switch, keyboard focus lands on the row that took the old one's place.
  useEffect(() => {
    const index = focusRow.current;
    if (index === null) return;
    focusRow.current = null;
    const target = rows[Math.min(index, rows.length - 1)];
    if (target) focusMessage(target.id);
  });

  // Select by id: a row on its way out still sits in the list while it animates away.
  const focusMessage = (id: string) => list.current?.querySelector<HTMLButtonElement>(`[data-id="${id}"]`)?.focus();

  const switchFolder = (next: Folder) => {
    setFolder(next);
    setOpen(null);
  };

  const move = (message: Message, to: Folder) => {
    const from = message.folder;
    setMessages((all) => all.map((item) => (item.id === message.id ? { ...item, folder: to } : item)));
    setOpen(null);
    setNotice({
      key: Date.now(),
      text: `${MOVED[to]}: ${message.subject}`,
      onUndo: () => {
        setMessages((all) => all.map((item) => (item.id === message.id ? { ...item, folder: from } : item)));
        setNotice({ key: Date.now(), text: `Put back: ${message.subject}` });
      },
    });
  };

  const toggle = (message: Message) => {
    setOpen((current) => (current === message.id ? null : message.id));
    if (message.unread) setMessages((all) => all.map((item) => (item.id === message.id ? { ...item, unread: false } : item)));
  };

  const onKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
    const target = event.target;
    if (!(target instanceof HTMLElement) || !target.dataset.row) return;
    const index = Number(target.dataset.row);
    const message = rows[index];
    if (!message) return;
    const key = event.key.toLowerCase();
    if (key === "arrowdown" || key === "arrowup") {
      event.preventDefault();
      const next = rows[Math.max(0, Math.min(rows.length - 1, index + (key === "arrowdown" ? 1 : -1)))];
      if (next) focusMessage(next.id);
    } else if (key === "arrowleft" || key === "arrowright") {
      event.preventDefault();
      const at = FOLDERS.findIndex((item) => item.id === folder);
      const next = FOLDERS[(at + (key === "arrowright" ? 1 : -1) + FOLDERS.length) % FOLDERS.length];
      if (next) {
        focusRow.current = 0;
        switchFolder(next.id);
      }
    } else if (key === "e" || key === "s") {
      let to: Folder | null = null;
      if (folder === "inbox") to = key === "e" ? "archive" : "snoozed";
      else if ((folder === "archive" && key === "e") || (folder === "snoozed" && key === "s")) to = "inbox";
      if (!to) return;
      event.preventDefault();
      focusRow.current = index;
      move(message, to);
    }
  };

  const hints =
    folder === "inbox"
      ? [
          ["E", "archive"],
          ["S", "snooze"],
        ]
      : [[folder === "archive" ? "E" : "S", "move to inbox"]];

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 px-5 pt-4 pb-3">
        <h2 id={titleId} className="flex items-baseline gap-2 text-base font-semibold">
          Harbour Street inbox
          <span className="text-sm font-normal tabular-nums text-muted-foreground">{unread === 0 ? "All read" : `${unread} unread`}</span>
        </h2>
        <label htmlFor={switchId} className="flex cursor-pointer items-center gap-2 text-sm text-muted-foreground">
          Unread only
          <Switch id={switchId} checked={unreadOnly} onCheckedChange={setUnreadOnly} />
        </label>
      </header>

      <FolderTabs folder={folder} counts={counts} onChange={switchFolder} panelId={panelId} />

      <div id={panelId} role="tabpanel" aria-labelledby={`${panelId}-${folder}`} className="min-h-88 px-2 py-2">
        <ul ref={list} aria-label="Messages" onKeyDown={onKeyDown} className="flex flex-col">
          <AnimatePresence initial={false}>
            {rows.map((message, index) => (
              <MessageRow
                key={message.id}
                message={message}
                index={index}
                expanded={open === message.id}
                onToggle={() => toggle(message)}
                onMove={(to) => {
                  focusRow.current = index;
                  move(message, to);
                }}
              />
            ))}
          </AnimatePresence>
        </ul>
        {rows.length === 0 ? (
          <p className="px-3 py-12 text-center text-sm text-muted-foreground">
            {unreadOnly ? "No unread messages here." : folder === "inbox" ? "Inbox zero. Every patient has an answer." : "Nothing here."}
          </p>
        ) : null}
      </div>

      <footer className="flex flex-wrap items-center gap-x-4 gap-y-2 border-t border-border px-5 py-3">
        <StatusLine notice={notice} idle="Up and down pick a message. Left and right switch folders." />
        <ul aria-label="Keys for the focused message" className="flex shrink-0 gap-3 text-xs text-muted-foreground">
          {hints.map(([key, action]) => (
            <li key={action} className="flex items-center gap-1.5">
              <Kbd>{key}</Kbd>
              {action}
            </li>
          ))}
        </ul>
      </footer>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import type { Person } from "../shared/people";

/** The three places a message can sit. */
export type Folder = "inbox" | "snoozed" | "archive";

/** The folders in tab order, with their names. */
export const FOLDERS: { id: Folder; label: string }[] = [
  { id: "inbox", label: "Inbox" },
  { id: "snoozed", label: "Snoozed" },
  { id: "archive", label: "Archive" },
];

/** One message in the Harbour Street front desk inbox. */
export interface Message {
  id: string;
  from: Person;
  subject: string;
  body: string;
  time: string;
  unread: boolean;
  folder: Folder;
}

/** The sample messages, newest first. */
export const MESSAGES: Message[] = [
  { id: "m1", from: { name: "Grace Whitfield", short: "Grace", hue: "pink" }, subject: "Can I move Thursday's physio?", body: "Hi, my son has a school play on Thursday afternoon. Could we move his 15:30 physio with Dr Haddad to Friday morning, any time before 11? Thank you, Grace.", time: "10:48", unread: true, folder: "inbox" },
  { id: "m2", from: { name: "Dr Omar Haddad", short: "Omar", hue: "purple" }, subject: "Running 20 minutes late", body: "Traffic on the ring road. Please let my 9:00 and 9:20 know I will be about 20 minutes late, and offer them the 12:40 slot if they would rather not wait.", time: "08:41", unread: true, folder: "inbox" },
  { id: "m3", from: { name: "Fernhill billing", short: "Billing", hue: "green" }, subject: "Your November invoice is ready", body: "The invoice for Harbour Street covers 4 practitioners and 1,284 reminders. It will be paid by card on November 5. No action is needed.", time: "Yesterday", unread: true, folder: "inbox" },
  { id: "m4", from: { name: "Samuel Okafor", short: "Samuel", hue: "blue" }, subject: "Lost my reminder link", body: "I deleted the text with my booking link by mistake. My appointment is on the 4th with the dentist. Can you send it again to the same number?", time: "Yesterday", unread: false, folder: "inbox" },
  { id: "m5", from: { name: "Mill Lane clinic", short: "Mill Lane", hue: "orange" }, subject: "Borrowing room 2 next week", body: "Our treatment room is being repainted on Monday and Tuesday. Could Dr Fischer use your room 2 from 13:00 to 17:00 on both days?", time: "Oct 29", unread: false, folder: "inbox" },
  { id: "m6", from: { name: "Ines Moreau", short: "Ines", hue: "amber" }, subject: "Feedback on the new check-in", body: "Checking in on the tablet took less than a minute. The only thing I missed was a way to update my address while I was there.", time: "Oct 28", unread: false, folder: "snoozed" },
  { id: "m7", from: { name: "Fernhill product", short: "Fernhill", hue: "blue" }, subject: "Waitlist auto-fill is on", body: "Freed slots now go to the first patient on your waitlist automatically. You can turn this off per practitioner in settings.", time: "Oct 27", unread: false, folder: "archive" },
];

/** The colour family of a person or a topic, drawn from the marketing tints that pass contrast in both themes. */
export type Hue = "blue" | "green" | "purple" | "pink" | "orange" | "amber";

/** A tinted surface with legible ink for each hue. */
export const HUE_TILE = {
  blue: "bg-marketing-blue-surface text-marketing-blue-ink",
  green: "bg-marketing-green-surface text-marketing-green-ink",
  purple: "bg-marketing-purple-surface text-marketing-purple-ink",
  pink: "bg-marketing-pink-surface text-marketing-pink-ink",
  orange: "bg-marketing-orange-surface text-marketing-orange-ink",
  amber: "bg-marketing-amber-surface text-marketing-amber-ink",
} satisfies Record<Hue, string>;

/** One person in the Fernhill sample world. */
export interface Person {
  name: string;
  /** The part of the name a sentence uses, such as "Amara". */
  short: string;
  hue: Hue;
}

/** Fernhill staff and the clinic people who appear across the support blocks. */
export const PEOPLE = {
  amara: { name: "Amara Osei", short: "Amara", hue: "blue" },
  tomas: { name: "Tomás Reyes", short: "Tomás", hue: "green" },
  lena: { name: "Lena Fischer", short: "Lena", hue: "purple" },
  kofi: { name: "Kofi Mensah", short: "Kofi", hue: "orange" },
  hana: { name: "Hana Sato", short: "Hana", hue: "pink" },
  priya: { name: "Priya Nair", short: "Priya", hue: "amber" },
  jonas: { name: "Jonas Berg", short: "Jonas", hue: "blue" },
  mia: { name: "Mia Clarke", short: "Mia", hue: "green" },
  omar: { name: "Omar Haddad", short: "Omar", hue: "purple" },
  ruth: { name: "Ruth Adeyemi", short: "Ruth", hue: "pink" },
} satisfies Record<string, Person>;

/** The key of a person in `PEOPLE`. */
export type PersonId = keyof typeof PEOPLE;

/** The one or two capital letters an avatar shows for a name. */
export function initials(name: string) {
  const parts = name.split(" ").filter(Boolean);
  return `${parts[0]?.[0] ?? ""}${parts.length > 1 ? (parts[parts.length - 1]?.[0] ?? "") : ""}`.toUpperCase();
}

/** A solid swatch for each hue, for a small dot or square beside a label. */
export const HUE_DOT = {
