  amber: "bg-marketing-amber-ink",
} satisfies Record<Hue, string>;

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useRef } from "react";

import { Button } from "@/components/ui/button";

import { FOLDERS, type Folder } from "./data";

/** Props for the folder tabs. */
export interface FolderTabsProps {
  folder: Folder;
  counts: Record<Folder, number>;
  onChange: (folder: Folder) => void;
  /** The id of the panel the tabs control. */
  panelId: string;
}

/**
 * Three folder tabs with counts. The indicator glides to the chosen tab, and
 * Left and Right move between tabs, as a tab list does.
 */
export function FolderTabs({ folder, counts, onChange, panelId }: FolderTabsProps) {
  const reduceMotion = useReducedMotion();
  const indicatorId = useId();
  const tabs = useRef(new Map<Folder, HTMLButtonElement>());

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
    if (step === 0) return;
    event.preventDefault();
    const index = FOLDERS.findIndex((item) => item.id === folder);
    const next = FOLDERS[(index + step + FOLDERS.length) % FOLDERS.length];
    if (!next) return;
    onChange(next.id);
    tabs.current.get(next.id)?.focus();
  };

  return (
    <div role="tablist" aria-label="Folders" onKeyDown={onKeyDown} className="flex gap-1 border-b border-border px-3">
      {FOLDERS.map((item) => {
        const selected = item.id === folder;
        return (
          <Button
            key={item.id}
            ref={(node) => {
              if (node) tabs.current.set(item.id, node);
              else tabs.current.delete(item.id);
            }}
            type="button"
            role="tab"
            id={`${panelId}-${item.id}`}
            aria-selected={selected}
            aria-controls={panelId}
            tabIndex={selected ? 0 : -1}
            variant={selected ? "ghost" : "ghost"}
            onClick={() => onChange(item.id)}
            className="relative min-h-11 sm:min-h-10"
          >
            <span className="font-medium">{item.label}</span>
            <span className="text-xs tabular-nums opacity-70">{counts[item.id]}</span>
            {selected ? (
              <motion.span
                layoutId={indicatorId}
                aria-hidden="true"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 44 }}
                className="absolute inset-x-2 -bottom-px h-0.5 rounded-full bg-chart-1"
              />
            ) : null}
          </Button>
        );
      })}
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ArchiveIcon, ClockIcon, InboxIcon } from "../icons";
import { PersonAvatar } from "../shared/person-avatar";
import type { Folder, Message } from "./data";

/** Props for one message row. */
export interface MessageRowProps {
  message: Message;
  index: number;
  expanded: boolean;
  onToggle: () => void;
  /** Moves the message: to the archive, to snoozed, or back to the inbox. */
  onMove: (to: Folder) => void;
}

const EASE = [0.2, 0, 0, 1] as const;

/**
 * One message: unread dot, avatar, sender, subject, preview and time. The row
 * opens in place to show the message and the actions that fit its folder.
 */
export function MessageRow({ message, index, expanded, onToggle, onMove }: MessageRowProps) {
  const reduceMotion = useReducedMotion();
  const bodyId = useId();
  const fade = reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 };
  const shown = reduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 };

  return (
    <motion.li layout={reduceMotion ? false : "position"} initial={fade} animate={shown} exit={fade} transition={{ duration: 0.22, ease: EASE }} className="overflow-hidden">
      <Button
        type="button"
        variant={expanded ? "secondary" : "ghost"}
        size="sm"
        data-row={index}
        data-id={message.id}
        aria-expanded={expanded}
        aria-controls={bodyId}
        onClick={onToggle}
        className="w-full justify-start text-left whitespace-normal"
      >
        <span className="grid w-full grid-cols-[0.5rem_auto_1fr_auto] items-center gap-x-3 px-3 py-2.5 font-normal">
        <span aria-hidden="true" className={cn("size-2 rounded-full", message.unread ? "bg-chart-1" : "bg-transparent")} />
        <PersonAvatar person={message.from} />
        <span className="flex min-w-0 flex-col">
          <span className={cn("truncate text-sm", message.unread ? "font-semibold text-foreground" : "text-foreground")}>
            {message.unread ? <span className="sr-only">Unread, </span> : null}
            {message.from.name}
          </span>
          <span className="truncate text-sm text-muted-foreground">
            <span className={cn(message.unread && "text-foreground")}>{message.subject}</span>
            <span className="ml-2 hidden @md:inline">{message.body}</span>
          </span>
        </span>
        <span className="self-start pt-0.5 text-xs whitespace-nowrap tabular-nums text-muted-foreground">{message.time}</span>
        </span>
      </Button>
      <AnimatePresence initial={false}>
        {expanded ? (
          <motion.div key="body" id={bodyId} initial={fade} animate={shown} exit={fade} transition={{ duration: 0.22, ease: EASE }} className="overflow-hidden">
            <div className="flex flex-col gap-3 pr-3 pb-3 pl-14 @md:pl-17">
              <p className="text-sm text-foreground">{message.body}</p>
              <div className="flex flex-wrap gap-2">
                {message.folder === "inbox" ? (
                  <>
                    <Button type="button" variant="outline" size="sm" onClick={() => onMove("archive")}>
                      <ArchiveIcon aria-hidden="true" />
                      Archive
                    </Button>
                    <Button type="button" variant="outline" size="sm" onClick={() => onMove("snoozed")}>
                      <ClockIcon aria-hidden="true" />
                      Snooze until Monday
                    </Button>
                  </>
                ) : (
                  <Button type="button" variant="outline" size="sm" onClick={() => onMove("inbox")}>
                    <InboxIcon aria-hidden="true" />
                    Move to inbox
                  </Button>
                )}
              </div>
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </motion.li>
  );
}

