import { cn } from "@/lib/utils";

import { HUE_TILE, type Person, initials } from "./people";

const SIZE = {
  sm: "size-6 text-[0.625rem]",
  md: "size-8 text-xs",
  lg: "size-10 text-sm",
} as const;

/** Props for a round initials avatar. */
export interface PersonAvatarProps {
  person: Person;
  size?: keyof typeof SIZE;
  className?: string;
}

/**
 * A round avatar with a person's initials on their own tint. It is decorative:
 * the name always sits beside it in text.
 */
export function PersonAvatar({ person, size = "md", className }: PersonAvatarProps) {
  return (
    <span
      aria-hidden="true"
      className={cn("inline-flex shrink-0 select-none items-center justify-center rounded-full font-semibold", SIZE[size], HUE_TILE[person.hue], className)}
    >
      {initials(person.name)}
    </span>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";

/** What the status line says after an action. */
export interface Notice {
  /** Changes with every action, so the same words still animate in again. */
  key: number;
  text: string;
  /** Puts the last move back, when it can be undone. */
  onUndo?: () => void;
}

/**
 * The line under the list that says what just happened. A new notice rises in
 * over the old one, and the whole line is a polite live region.
 */
export function StatusLine({ notice, idle }: { notice: Notice | null; idle: string }) {
  const reduceMotion = useReducedMotion();
  const text = notice?.text ?? idle;
  return (
    <div role="status" className="relative flex min-h-6 min-w-0 flex-1 items-center overflow-hidden">
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={notice?.key ?? "idle"}
          initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -8 }}
          transition={{ duration: 0.18, ease: [0.2, 0, 0, 1] }}
          className="flex min-w-0 items-center gap-2 text-sm text-muted-foreground"
        >
          <span className="truncate">{text}</span>
          {notice?.onUndo ? (
            <Button type="button" variant="link" size="sm" onClick={notice.onUndo}>
              Undo
            </Button>
          ) : null}
        </motion.span>
      </AnimatePresence>
    </div>
  );
}
